    cmd = old[3:old.index('--junitxml=D:/githv/agomTradePro/.tmp/ash-c3a-green-unit-02.xml')]
elif tag.startswith('green-http'):
    cmd = ['-m', 'pytest', '-q', '--ds=ash_c3b_sqlite_settings', '--no-migrations', '--create-db', 'tests/component/account/test_transaction_fee_mcp_http_journey.py', 'tests/component/account/test_transaction_fee_post_once.py', 'tests/component/account/test_c3b_capital_flow_import_http.py']
