    cmd = ['-m', 'pytest', '-q', '--ds=ash_c3b_sqlite_settings', 'tests/unit/test_active_plan_registry.py']
elif tag.startswith('registry'):
    cmd = ['scripts/check_active_plan_registry.py', '--format', 'text']
